def min_lexicographic_string(n, k, s):
    s = list(s)
    zeros = s.count('0')
    ones = n - zeros
    result = ['1'] * n

    # Place zeros in the result string
    for i in range(zeros):
        pos = i
        while pos < n and s[pos] == '1':
            pos += 1
        if pos < n:
            result[pos] = '0'
            s[pos] = '1'
            k -= pos - i
            if k < 0:
                return ''.join(result)

    return ''.join(result)

