def min_lexicographic_string(n, k, s):
    s = list(s)
    swaps = 0
    for i in range(n):
        for j in range(i + 1, n):
            if swaps >= k:
                break
            if s[i] > s[j]:
                s[i], s[j] = s[j], s[i]
                swaps += 1
        if swaps >= k:
            break
    return ''.join(s)

